INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('32bfe0dc-3c4d-5f80-9a27-b31fab527ec3'::uuid, '403c3e19-7903-5ed7-bd19-05414683e5e8'::uuid, 'Projet 1', 'Chez « ArtVitrage », qualité, conseil et respect des délais sont des valeurs qui priment, grâce aux nombreux artisans formés préalablement par l entreprise, ces valeurs sont respectées et tout projet dispose de toute l attention nécessaire.', '["http://artvitrage.ma/wp-content/uploads/2018/01/Sans-titre-2-150x150.png"]'::jsonb, 'http://artvitrage.ma/wp-content/uploads/2018/01/Sans-titre-2-150x150.png', 'Marrakech', (SELECT id FROM public.internal_categories WHERE code = '3.3.3' LIMIT 1));
