INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('2f9a9f55-32aa-5a4e-8539-edded25b3f79'::uuid, '967b1c14-4cf9-5dc3-b313-1d39bc628c7b'::uuid, 'Pouvez-vous simuler et designer mon projet ?', 'Oui, notre bureau de design vous accompagne dans l’élaboration de zellige sur-mesure, en étudiant les spécificités de chaque espace. Piscines, terrasses, cheminées, salles de bains, crédences de cuisines, sols ou murs, le laboratoire d''Aït Manos, fort de son savoir-faire et à l’écoute de vos ambitions, conçoit et fabrique du zellige traditionnel marocain adapté à toutes les surfaces, en répondant', '["https://aitmanos.com/cdn/shop/files/20211201_WorkshopNo5_Winflo_Web_8.jpg?crop=center&height=1080&v=1761831214&width=1201"]'::jsonb, 'https://aitmanos.com/cdn/shop/files/20211201_WorkshopNo5_Winflo_Web_8.jpg?crop=center&height=1080&v=1761831214&width=1201', 'Casablanca', (SELECT id FROM public.internal_categories WHERE code = '3.1.5' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('dbd47cbd-2598-5f7f-89f9-08cf1b5c0962'::uuid, '967b1c14-4cf9-5dc3-b313-1d39bc628c7b'::uuid, 'Artisan créateur de Zellige, spécialiste des grands projets internationaux', 'Nous collaborons avec les cabinets d’architecture et de décoration du monde entier pour concevoir et réaliser des revêtements en zellige traditionnel, alliant exigence esthétique, savoir-faire patrimonial et engagement durable.', '["https://aitmanos.com/cdn/shop/files/20211201_WorkshopNo5_Winflo_Web_8.jpg?v=1761831214&width=136"]'::jsonb, 'https://aitmanos.com/cdn/shop/files/20211201_WorkshopNo5_Winflo_Web_8.jpg?v=1761831214&width=136', 'Casablanca', (SELECT id FROM public.internal_categories WHERE code = '3.1.5' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('45f887c5-b046-5088-b660-e3fc89acc11a'::uuid, '967b1c14-4cf9-5dc3-b313-1d39bc628c7b'::uuid, 'Décrivez-nous votre projet.', 'Les champs marqués d un astérisque (*) sont obligatoires. Ce site est protégé par hCaptcha, et la Politique de confidentialité et les Conditions de service de hCaptcha s’appliquent.', '["https://aitmanos.com/cdn/shop/files/20211201_WorkshopNo5_Winflo_Web_8.jpg?v=1761831214&width=160"]'::jsonb, 'https://aitmanos.com/cdn/shop/files/20211201_WorkshopNo5_Winflo_Web_8.jpg?v=1761831214&width=160', 'Casablanca', (SELECT id FROM public.internal_categories WHERE code = '3.1.5' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('d6557f50-27f8-5e6a-8e19-324d4c3e2285'::uuid, '967b1c14-4cf9-5dc3-b313-1d39bc628c7b'::uuid, 'Nos réalisations', 'Chaque réalisation Aït Manos incarne l’excellence d’un savoir-faire ancestral. Un art vivant, durable et profondément enraciné dans les grandes traditions du zellige.', '["https://aitmanos.com/cdn/shop/files/20211201_WorkshopNo5_Winflo_Web_8.jpg?v=1761831214&width=180"]'::jsonb, 'https://aitmanos.com/cdn/shop/files/20211201_WorkshopNo5_Winflo_Web_8.jpg?v=1761831214&width=180', 'Casablanca', (SELECT id FROM public.internal_categories WHERE code = '3.1.5' LIMIT 1));
