INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('67b7ece1-879c-53fc-8a36-b412b582f709'::uuid, '8cf0c853-881f-5c90-b891-d0d37ade7adc'::uuid, 'L’entreprise BELKAS BUSINESS réalisation des bâtiments neufs de tous types.', 'La connaissances techniques de la maçonnerie, du béton qu’il soit banché, armé ou précontraint, lui ont permis d’entreprendre des bâtiments a l’usage (résidences, et logements de toutes sortes).', '["https://constructionmarrakech.com/wp-content/uploads/2020/04/amenagement-exterieur-750x500.jpg"]'::jsonb, 'https://constructionmarrakech.com/wp-content/uploads/2020/04/amenagement-exterieur-750x500.jpg', 'Marrakech', (SELECT id FROM public.internal_categories WHERE code = '3.1.5' LIMIT 1));
