INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('96e61e6a-f520-5cee-960c-860ba4e5326b'::uuid, '753ce500-0c3f-5c83-bd42-cdc236d9fa79'::uuid, 'Des projets qui traduisent une vision', 'Chaque réalisation porte en elle une ambition, un défi et une histoire. Chez Structures Valley, nous considérons chaque projet comme une opportunité de créer des espaces qui génèrent de la valeur, améliorent les usages et s’inscrivent durablement dans leur environnement.', '["https://structuresvalley.com/wp-content/uploads/2020/10/sidekix-media-zLT3VqWEgOQ-unsplash.jpg"]'::jsonb, 'https://structuresvalley.com/wp-content/uploads/2020/10/sidekix-media-zLT3VqWEgOQ-unsplash.jpg', 'Casablanca', (SELECT id FROM public.internal_categories WHERE code = '3.4.3' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('e813da40-1560-54e3-a26f-d7603467d711'::uuid, '753ce500-0c3f-5c83-bd42-cdc236d9fa79'::uuid, 'Structuration de projets techniques nécessitant maîtrise des flux, optimisation des espaces et rigueur opérationnelle.', 'Une méthode structurée, de l’idée à la livraison Chaque projet est abordé avec une démarche claire, progressive et maîtrisée. Notre méthode permet de transformer une vision initiale en une réalisation concrète, cohérente et durable.', '["https://structuresvalley.com/wp-content/uploads/2020/10/sidekix-media-zLT3VqWEgOQ-unsplash-300x189.jpg"]'::jsonb, 'https://structuresvalley.com/wp-content/uploads/2020/10/sidekix-media-zLT3VqWEgOQ-unsplash-300x189.jpg', 'Casablanca', (SELECT id FROM public.internal_categories WHERE code = '3.4.3' LIMIT 1));
