INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('2a37b22a-5aa6-57d2-adb8-21df2f7414ea'::uuid, 'f97d3a54-0630-5703-8346-a379288d8b2a'::uuid, 'Écoute et étude globale du projet', 'Nous prenons le temps de comprendre votre projet : vos besoins, vos contraintes, vos attentes, votre budget. Si vous avez des plans, nous les étudions. Si vous n en avez pas, nous vous guidons vers les bonnes solutions. Nous visitons systématiquement le terrain ou le bâtiment existant. C est indispensable pour établir un devis réaliste et réaliser une étude globale complète. Une mauvaise évaluatio', '["https://francobat.ma/wp-content/uploads/2025/12/Nouveau-projet-11.png"]'::jsonb, 'https://francobat.ma/wp-content/uploads/2025/12/Nouveau-projet-11.png', 'Tanger', (SELECT id FROM public.internal_categories WHERE code = '3.1.5' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('d4538018-a5b1-5585-b50b-ffc80adad936'::uuid, 'f97d3a54-0630-5703-8346-a379288d8b2a'::uuid, 'CONSTRUCTION DE VILLAS', 'Construction de maisons individuelles et villas Construction de maisons individuelles et villas Construire sa propre maison, c est un projet de construction de vie. Nous le savons, et c est pour ça que nous y accordons une attention particulière. En tant que constructeur de maisons individuelles, chaque villa que nous construisons est pensée en fonction du terrain, du climat local, des envies du c', '["https://francobat.ma/wp-content/uploads/2025/12/Securite-sur-le-chantier.png"]'::jsonb, 'https://francobat.ma/wp-content/uploads/2025/12/Securite-sur-le-chantier.png', 'Tanger', (SELECT id FROM public.internal_categories WHERE code = '3.1.5' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('ed791efc-b970-546a-9de1-3614c4e2e19a'::uuid, 'f97d3a54-0630-5703-8346-a379288d8b2a'::uuid, 'Construction de villa', 'Beaucoup de nos clients sont des particuliers qui construisent leur première maison. C est souvent un projet de vie, parfois le fruit de plusieurs années d économies. Nous le savons, et nous prenons cette responsabilité très au sérieux. Notre rôle est de vous accompagner tout au long du processus, de vous expliquer les étapes, de vous conseiller sur les choix techniques, et de livrer une maison ne', '["https://francobat.ma/wp-content/uploads/2025/12/A-propos-de-nous-FRANCOBAT.png"]'::jsonb, 'https://francobat.ma/wp-content/uploads/2025/12/A-propos-de-nous-FRANCOBAT.png', 'Tanger', (SELECT id FROM public.internal_categories WHERE code = '3.1.5' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('a89409c8-740d-5cfc-958a-f6b4f9650c20'::uuid, 'f97d3a54-0630-5703-8346-a379288d8b2a'::uuid, 'Construction de maisons individuelles et villas', 'Construction de maisons individuelles et villas Construire sa propre maison, c est un projet de construction de vie. Nous le savons, et c est pour ça que nous y accordons une attention particulière. En tant que constructeur de maisons individuelles, chaque villa que nous construisons est pensée en fonction du terrain, du climat local, des envies du client et bien sûr du budget disponible.', '["https://francobat.ma/wp-content/uploads/2025/12/A-propos-de-nous-FRANCOBAT-980x980.png"]'::jsonb, 'https://francobat.ma/wp-content/uploads/2025/12/A-propos-de-nous-FRANCOBAT-980x980.png', 'Tanger', (SELECT id FROM public.internal_categories WHERE code = '3.1.5' LIMIT 1));
