INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('277d1928-20d0-58b1-87a5-47c08261e8cb'::uuid, 'd88029e6-14b0-588a-8dda-0216eaf48f1f'::uuid, 'HASSAN EL IDRISSI DIRECTEUR DES PROJETS D''INFRASTRUCTURE', 'Nous avons confié à GECOVA un projet de grande envergure, et leur expertise a été impressionnante. Leur équipe a non seulement respecté les délais, mais a également maintenu les normes de qualité les plus élevées, surpassant ainsi nos attentes. Le professionnalisme de GECOVA, couplé à leur capacité à gérer des défis complexes, en fait un partenaire de confiance pour nos futurs projets d''infrastruc', '["https://gecova.ma/wp-content/uploads/2024/06/builderon-img5.png"]'::jsonb, 'https://gecova.ma/wp-content/uploads/2024/06/builderon-img5.png', 'Tanger', (SELECT id FROM public.internal_categories WHERE code = '3.1.5' LIMIT 1));
