INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('182c3631-9140-527d-8df6-5e26d9d4f68a'::uuid, '988ca152-8766-5fd5-81b9-577c70dd167f'::uuid, 'Parlons de votre projet.', 'Une maison, un immeuble, un hôtel ? Décrivez-nous votre projet. Vous avez des plans ou un cahier des charges (C.P.S.) ? Joignez-les. Sinon, une simple description suffit : l étude est gratuite et sans engagement.', '["https://www.gmtdesign.ma/_next/image?url=%2Fimages%2Fgenerated%2Fprojet-01-villa-v2.webp&w=384&q=75"]'::jsonb, 'https://www.gmtdesign.ma/_next/image?url=%2Fimages%2Fgenerated%2Fprojet-01-villa-v2.webp&w=384&q=75', 'Tanger', (SELECT id FROM public.internal_categories WHERE code = '3.1.5' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('aa0eb281-9a66-58b1-b6c8-502e2613da0b'::uuid, '988ca152-8766-5fd5-81b9-577c70dd167f'::uuid, 'Un projet, deux façons d en parler.', 'Je construis ou je rénove ma maison Fenêtres, baies coulissantes, garde-corps, vérandas : nous vous expliquons simplement et nous vous chiffrons clairement. Aucun cahier des charges à fournir.', '["https://www.gmtdesign.ma/_next/image?url=%2Fimages%2Fgenerated%2Fprojet-01-villa-v2.webp&w=640&q=75"]'::jsonb, 'https://www.gmtdesign.ma/_next/image?url=%2Fimages%2Fgenerated%2Fprojet-01-villa-v2.webp&w=640&q=75', 'Tanger', (SELECT id FROM public.internal_categories WHERE code = '3.1.5' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('703ada3d-1fd7-5e75-ad90-69d697ad68c6'::uuid, 'e9164ffc-521c-5cdd-93e4-c1d1f13aa5f5'::uuid, 'Voir Toutes les Réalisations', 'À Propos de Galeon BTP Une Entreprise Ancrée dans l’Excellence Fondée au Maroc, Galeon BTP s’est imposée comme un acteur incontournable du BTP grâce à son expertise technique, son parc matériel moderne et son engagement total envers la qualité. Spécialiste du revêtement routier et du bitume Maroc, nous produisons et posons des enrobés bitumineux à chaud sur tous types de voirie Maroc : routes nati', '["https://www.galeon.ma/wp-content/uploads/Assainissement-Projet-Jorref-Afriquia.jpg"]'::jsonb, 'https://www.galeon.ma/wp-content/uploads/Assainissement-Projet-Jorref-Afriquia.jpg', 'Casablanca', (SELECT id FROM public.internal_categories WHERE code = '3.4.1' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('594a1007-f4bc-57bb-a5e7-d86645212e96'::uuid, 'e9164ffc-521c-5cdd-93e4-c1d1f13aa5f5'::uuid, '+212 6XX XX XX XX Afficher', 'Email: [email&#160;protected] Horaires: Lun-Ven 8h-18h / Sam 8h-13h &copy; 2026 Galeon BTP. Tous droits réservés. Entreprise de BTP au Maroc {"prefetch":[{"source":"document","where":{"and":[{"href_matches":"/*"},{"not":{"href_matches":["/wp-*.php","/wp-admin/*","/wp-content/uploads/*","/wp-cont', '["https://www.galeon.ma/wp-content/uploads/finition-bouthmane.jpg"]'::jsonb, 'https://www.galeon.ma/wp-content/uploads/finition-bouthmane.jpg', 'Casablanca', (SELECT id FROM public.internal_categories WHERE code = '3.4.1' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('c5b8302a-2f5c-5237-9ebf-c255d82f5d22'::uuid, 'e9164ffc-521c-5cdd-93e4-c1d1f13aa5f5'::uuid, 'De la conception à la réalisation, Galeon BTP intervient sur l’ensemble des métiers du BTP avec rigueur et savoir-faire.', 'Revêtements routiers haute performance, parkings et voiries. Fabrication et pose d’enrobés avec notre centrale Ermont 160t.', '["https://www.galeon.ma/wp-content/uploads/enrobe-bouthmane.jpg"]'::jsonb, 'https://www.galeon.ma/wp-content/uploads/enrobe-bouthmane.jpg', 'Casablanca', (SELECT id FROM public.internal_categories WHERE code = '3.4.1' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('dec9f959-c2d0-57b3-a0fd-3f9ec791be2f'::uuid, 'e9164ffc-521c-5cdd-93e4-c1d1f13aa5f5'::uuid, 'VRD, terrassement, fondations et assainissement. Des solutions complètes pour vos projets d’infrastructure.', 'Voirie, réseaux et infrastructure publique. Galeon BTP accompagne les collectivités et donneurs d’ordre publics et privés.', '["https://www.galeon.ma/wp-content/uploads/galeon-btp-parking-enrobe-afriquia-bouthmane.jpg"]'::jsonb, 'https://www.galeon.ma/wp-content/uploads/galeon-btp-parking-enrobe-afriquia-bouthmane.jpg', 'Casablanca', (SELECT id FROM public.internal_categories WHERE code = '3.4.1' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('4f551316-fc21-5b29-893d-01937f440e6b'::uuid, '560add02-4909-5c26-89b7-d196595e05fb'::uuid, 'Les résidences de la colline I', 'Tout au long de ses années d’existence, Générale de projets a su développer un savoir faire adapté aux besoins du marché marocain. Depuis sa création en 2000, l’entreprise a réalisé plusieurs projets de grande envergure tels que des bâtiments publics, des sièges d’administrations, ou encore des Résidences et hôtels de haut standing.', '["https://www.generaledeprojets.ma/wp-content/uploads/2022/12/594C2C31-7367-435F-AD99-999FBF5AC22D-min-scaled.jpg"]'::jsonb, 'https://www.generaledeprojets.ma/wp-content/uploads/2022/12/594C2C31-7367-435F-AD99-999FBF5AC22D-min-scaled.jpg', 'Rabat', (SELECT id FROM public.internal_categories WHERE code = '3.1.5' LIMIT 1));
