INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('5614016c-6b4d-5084-bf6b-d4b72a3b0ded'::uuid, '1013ccdd-59ac-5aa4-96c8-45fceb919e09'::uuid, 'Des projets d''infrastructure avec précision', 'Découvrez notre processus de gestion de projets d infrastructure, de la conception à la réalisation. Notre approche méthodique garantit la qualité, la sécurité et la durabilité de chaque intervention. Nous utilisons des techniques innovantes et des matériaux performants pour des résultats fiables en assainissement, eau potable, voirie et énergie électrique .', '["https://hs-infra.com/wp-content/uploads/2025/06/industrial-worker-female-builder-with-working-documents-outdoor-construction-1024x682.jpg"]'::jsonb, 'https://hs-infra.com/wp-content/uploads/2025/06/industrial-worker-female-builder-with-working-documents-outdoor-construction-1024x682.jpg', 'Tanger', (SELECT id FROM public.internal_categories WHERE code = '3.1.2' LIMIT 1));
