INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('ad946a57-733b-5294-b9a3-4d6914801529'::uuid, '1013ccdd-59ac-5aa4-96c8-45fceb919e09'::uuid, 'PROJETS EN VEDETTE', 'Découvrez Nos Succès Avérés dans Chaque Construction Des Projets d’envergure Explorez nos réalisations emblématiques au Maroc. De l infrastructure hydraulique à l électrification rurale , chaque projet témoigne de notre expertise et de notre engagement pour des infrastructures durables .', '["https://hs-infra.com/wp-content/uploads/2025/06/industrial-worker-female-builder-with-working-documents-outdoor-construction-768x512.jpg"]'::jsonb, 'https://hs-infra.com/wp-content/uploads/2025/06/industrial-worker-female-builder-with-working-documents-outdoor-construction-768x512.jpg', 'Tanger', (SELECT id FROM public.internal_categories WHERE code = '3.1.2' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('e0348d48-55f1-5b1b-af4f-5155c2a246d0'::uuid, '1013ccdd-59ac-5aa4-96c8-45fceb919e09'::uuid, 'ESSAOUIRA :Projet en cours', 'Un Parc Matériel Complet pour Vos Projets d''Infrastructure HS INFRA dispose d un parc de matériel et d équipements moderne et étendu, entièrement détenu, garantissant une autonomie et une réactivité optimales pour tous vos projets d infrastructure.', '["https://hs-infra.com/wp-content/uploads/2025/06/industrial-worker-female-builder-with-working-documents-outdoor-construction-1536x1024.jpg"]'::jsonb, 'https://hs-infra.com/wp-content/uploads/2025/06/industrial-worker-female-builder-with-working-documents-outdoor-construction-1536x1024.jpg', 'Tanger', (SELECT id FROM public.internal_categories WHERE code = '3.1.2' LIMIT 1));
