INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('844eb7e7-729f-58ad-9c6e-43dd8cb1d3ef'::uuid, 'b6b7045e-cde5-5e58-8a5a-96cfa36797b6'::uuid, 'Votre futur projet devient une réalité', 'Nous sommes une entreprise de construction passionnée par notre métier et le succès de nos partenaires. Nous sommes fiers d''être des fournisseurs de solutions en bâtiments, gros oeuvre et second oeuvre à Marrakech et dans tout le Maroc.', '["https://www.indaouzal.com/assets/images/projets/1-5.jpg"]'::jsonb, 'https://www.indaouzal.com/assets/images/projets/1-5.jpg', 'Marrakech', (SELECT id FROM public.internal_categories WHERE code = '3.1.5' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('24b0e869-491c-54f9-a60f-f41e999fc7bc'::uuid, 'b6b7045e-cde5-5e58-8a5a-96cfa36797b6'::uuid, 'Engagée à livrer des projets de construction de haute qualité et à innover dans leurs conception !', 'Projets de construction et rénovation jusqu''au Aujourd''hui Pourtant, ceux qui adoptent le changement prospèrent, construisant des projets plus grands, meilleurs, plus rapides et plus solides que jamais.', '["https://www.indaouzal.com/assets/images/projets/5-5.jpg"]'::jsonb, 'https://www.indaouzal.com/assets/images/projets/5-5.jpg', 'Marrakech', (SELECT id FROM public.internal_categories WHERE code = '3.1.5' LIMIT 1));
