INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('efd6616d-6d2e-54e7-9407-74ddd04758f5'::uuid, '65bc6096-e826-5f26-8fde-4b7211287bc6'::uuid, 'Serpentin Cuivre', 'Votre artisan plombier à Marrakech intervient sous 30 minutes 24h/24 et 7j/7 pour la réparation de fuites d''eau, le débouchage de canalisations, le remplacement de chauffe-eau et l''installation sanitaire dans tous les quartiers de Marrakech (Guéliz, Hivernage, Palmeraie, Targa, Agdal, Médina, etc.). Devis 100% gratuit et sans engagement. <path d="M22 16.92v3a2 2 0 0 1-2.18 2 19.79 19.79 0 0 1-8.63', '["https://marrakechplombier.com/assets/images/hero-realisation-vitra-sanitaire.jpg"]'::jsonb, 'https://marrakechplombier.com/assets/images/hero-realisation-vitra-sanitaire.jpg', 'Marrakech', (SELECT id FROM public.internal_categories WHERE code = '3.2.2' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('47447009-706a-5e75-bbbe-86b3a8efc71f'::uuid, '65bc6096-e826-5f26-8fde-4b7211287bc6'::uuid, 'Hammam Beldi', 'Serpentin Cuivre Votre artisan plombier à Marrakech intervient sous 30 minutes 24h/24 et 7j/7 pour la réparation de fuites d''eau, le débouchage de canalisations, le remplacement de chauffe-eau et l''installation sanitaire dans tous les quartiers de Marrakech (Guéliz, Hivernage, Palmeraie, Targa, Agdal, Médina, etc.). Devis 100% gratuit et sans engagement. <div class', '["https://marrakechplombier.com/assets/images/hero-realisation-hammam-zellige.jpg"]'::jsonb, 'https://marrakechplombier.com/assets/images/hero-realisation-hammam-zellige.jpg', 'Marrakech', (SELECT id FROM public.internal_categories WHERE code = '3.2.2' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('55bcdc2a-c4a8-5c71-bbbc-1529101770e1'::uuid, '65bc6096-e826-5f26-8fde-4b7211287bc6'::uuid, 'Nos Réalisations', 'À Propos de Nous Blog &amp; Conseils Contactez-nous Contact Urgence 24/7 <path d="M22 16.92v3a2 2 0 0 1-2.18 2 19.79 19.79 0 0 1-8.63-3.07 19.5 19.5 0 0 1-6-6 19.79 19.79 0 0 1-3.07-8.67A2 2 0 0 1 4.11 2h3a2 2 0 0 1 2 1.72 12.84 12.84 0 0 0 .7 2.81 2 2 0 0 1-.45 2.11L8.09 9.91a16 16 0 0 0 6 6l1.27', '["https://marrakechplombier.com/assets/images/depannage-evier-cuisine-marrakech.jpg"]'::jsonb, 'https://marrakechplombier.com/assets/images/depannage-evier-cuisine-marrakech.jpg', 'Marrakech', (SELECT id FROM public.internal_categories WHERE code = '3.2.2' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('5823d960-959d-5f10-9983-02b7bacf1e80'::uuid, '65bc6096-e826-5f26-8fde-4b7211287bc6'::uuid, 'Maintenance Solaire Entretien Chauffe-Eau Solaire Chaffoteaux 📍 Palmeraie, Marrakech →', 'PROXIMITÉ &amp; RÉACTIVITÉ EN 30 MINUTES Zones d''Intervention de Votre Plombier à Marrakech Nos équipes mobiles d''artisan plombiers interviennent 24h/24 et 7j/7 avec du matériel de pointe dans tous les quartiers de Marrakech et ses environs. <div style="display: flex; flex-wrap: wrap; gap: 0.', '["https://marrakechplombier.com/assets/images/artisan-plombier-chauffage-cuivre.jpg"]'::jsonb, 'https://marrakechplombier.com/assets/images/artisan-plombier-chauffage-cuivre.jpg', 'Marrakech', (SELECT id FROM public.internal_categories WHERE code = '3.2.2' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('26298f8f-eff3-5ca6-9347-2ba337a56a10'::uuid, '9a0e5fd3-21ec-5d2b-a97f-caad010094a7'::uuid, 'Nos réalisations →', '🏗 Construction neuve 🧱 Réparation structurelle 📐 Conduite de chantier 💧 Étanchéité 🔲 Carrelage Notre identité À propos de NEUFSTRUC Basée à Casablanca, NEUFSTRUC SARLAU est une entreprise de construction spécialisée dans la construction neuve, la conduite de chantier et les travaux de bâtiment, du gros œuvre au second œuvre. Un seul interlocuteur : de la gestion du chantier aux finitions. Rigueur', '["http://www.neufstruc.ma/images/svc-chantier.jpg"]'::jsonb, 'http://www.neufstruc.ma/images/svc-chantier.jpg', 'Casablanca', (SELECT id FROM public.internal_categories WHERE code = '3.1.5' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('e700f6a2-9762-5a75-9d40-b09b11750c0a'::uuid, '9a0e5fd3-21ec-5d2b-a97f-caad010094a7'::uuid, 'Suivi et réalisation de projets', 'Cloisons, réseaux, enduits, plâtrerie, carrelage : tous les corps d''état sont coordonnés sous une même direction de chantier, pour un résultat homogène et sans retard.', '["http://www.neufstruc.ma/images/galerie-1.jpg"]'::jsonb, 'http://www.neufstruc.ma/images/galerie-1.jpg', 'Casablanca', (SELECT id FROM public.internal_categories WHERE code = '3.1.5' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('caeb80d6-f032-5ec8-a23c-6403d68f8822'::uuid, '9a0e5fd3-21ec-5d2b-a97f-caad010094a7'::uuid, 'Pourquoi nous choisir pour vos projets ?', 'Nous ne construisons pas seulement des bâtiments : nous bâtissons la confiance. Notre priorité est de transformer vos idées en ouvrages durables et de qualité.', '["http://www.neufstruc.ma/images/galerie-2.jpg"]'::jsonb, 'http://www.neufstruc.ma/images/galerie-2.jpg', 'Casablanca', (SELECT id FROM public.internal_categories WHERE code = '3.1.5' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('208b34e2-8686-5518-bfb9-ef5f53b3271f'::uuid, '9a0e5fd3-21ec-5d2b-a97f-caad010094a7'::uuid, 'Quels types de projets réalisez-vous ?', 'Constructions neuves, réhabilitations, réparations structurelles, étanchéité, carrelage et second œuvre, pour particuliers et entreprises.', '["http://www.neufstruc.ma/images/galerie-3.jpg"]'::jsonb, 'http://www.neufstruc.ma/images/galerie-3.jpg', 'Casablanca', (SELECT id FROM public.internal_categories WHERE code = '3.1.5' LIMIT 1));
